  every: "FOURTY_FIVE_SECONDS" | "ONE_MINUTE" | "FIVE_MINUTES" | "TEN_MINUTES" | "THIRTY_MINUTES" | "ONE_HOUR" | "END_SESSION" | "END_OF_DAY";
  /** When the notification is sent: IN (stock enters the condition), OUT (stock leaves it), IN_OUT (both) */
  send_on: "IN" | "OUT" | "IN_OUT";
  /** Visibility list, e.g. ["public"] or plan names */
  scope: string[] | null;
  /** Alert formula */
  formula: string;
