export interface AlertsTestResponse {
  /** true if the formula is valid and evaluated without errors; false on error or high-risk pattern */
  success: boolean;
  /** Tested formula after automatic normalization (e.g. division guards) */
  formula: string;
  /** Number of active stocks evaluated (after the category filter) */
  total_stocks: number;
  /** Number of stocks matching the formula */
  matched_count: number;
  /** Codes of matching stocks (max 100) */
  matched_stocks: string[];
  /** Error message (present only on failure); when success is false it holds the joined warnings or the error */
  error?: string;
  /** Evaluation results of the first 5 stocks (absent when validation fails before evaluation) */
  sample_results?: AlertsTestSampleResults[];
  /** Formula warnings (absent when empty) */
  warnings?: AlertsTestWarnings[];
  /** Applied index category filter (present only when sent) */
  category_filter?: string[];
  /** Number of stocks passing the category filter */
  category_filtered_count?: number;
  /** Same as error; present only when success is false */
  message?: string;
}

export interface AlertsTestSampleResults {
  /** Stock code */
  code: string;
  /** Whether the stock matches the formula */
  matched: boolean;
  /** Evaluation error (present only on failure) */
  error?: string;
  /** Formula after functions were resolved for this stock */
  processed_formula?: string;
}

export interface AlertsTestWarnings {
  /** Warning level */
  level: "info" | "warning" | "error";
  /** Warning message */
  message: string;
  /** Formula fragment that triggered the warning */
  pattern: string;
  /** Suggested fix (optional) */
  suggestion?: string;
}

