/** Query parameters for `GET /analysis/running-trade/{code}`. */
export interface StockRunningTradeParams {
  /** Tanggal data (`YYYY-MM-DD`). Gunakan hari bursa; tanggal libur bursa dapat menghasilkan data kosong. Format: `YYYY-MM-DD`. Example: `2026-03-25`. */
  date: string;
  /** Nomor halaman, dimulai dari 1. Default: `1`. Min: `1`. Example: `1`. */
  page?: number;
  /** Jumlah transaksi per halaman. Default: `50`. Min: `1`. Max: `1000`. Example: `50`. */
  limit?: number;
  /** Sisi transaksi: `BUY` = match di harga offer (inisiatif beli), `SELL` = match di harga bid (inisiatif jual), `ALL` = seluruh transaksi. Diabaikan saat jam bursa (tanggal hari ini, 08:45–16:15 WIB pada hari bursa); hanya berlaku pada pengambilan data sehari penuh. Default: `ALL`. Example: `ALL`. */
  type?: "ALL" | "BUY" | "SELL";
  /** Kolom pengurutan: `TIME` = waktu transaksi, `PRICE` = harga, `VOLUME` = volume. Diabaikan saat jam bursa (tanggal hari ini, 08:45–16:15 WIB pada hari bursa); hanya berlaku pada pengambilan data sehari penuh. Default: `TIME`. Example: `TIME`. */
  orderby?: "TIME" | "PRICE" | "VOLUME";
  /** Volume minimal transaksi yang ditampilkan, dalam lembar (1 lot = 100 lembar). Berguna untuk menyaring transaksi besar. Diabaikan saat jam bursa (tanggal hari ini, 08:45–16:15 WIB pada hari bursa); hanya berlaku pada pengambilan data sehari penuh. Min: `0`. Example: `100`. */
  minimum?: number;
  /** Volume maksimal transaksi yang ditampilkan, dalam lembar (1 lot = 100 lembar). Diabaikan saat jam bursa (tanggal hari ini, 08:45–16:15 WIB pada hari bursa); hanya berlaku pada pengambilan data sehari penuh. Min: `0`. Example: `10000`. */
  maximum?: number;
  /** Jenis pasar: `ALL` = seluruh pasar, `RG` = Pasar Reguler, `NG` = Pasar Negosiasi, `TN` = Pasar Tunai. Diabaikan saat jam bursa (tanggal hari ini, 08:45–16:15 WIB pada hari bursa); hanya berlaku pada pengambilan data sehari penuh. Default: `ALL`. Example: `RG`. */
  market?: "ALL" | "RG" | "NG" | "TN";
  /** Harga terendah transaksi yang ditampilkan (Rupiah). Menampilkan transaksi dengan harga >= `pricefrom`. Diabaikan saat jam bursa (tanggal hari ini, 08:45–16:15 WIB pada hari bursa); hanya berlaku pada pengambilan data sehari penuh. Min: `1`. Example: `9000`. */
  pricefrom?: number;
  /** Harga tertinggi transaksi yang ditampilkan (Rupiah). Menampilkan transaksi dengan harga <= `priceto`. Diabaikan saat jam bursa (tanggal hari ini, 08:45–16:15 WIB pada hari bursa); hanya berlaku pada pengambilan data sehari penuh. Min: `1`. Example: `9500`. */
  priceto?: number;
  /** Jam awal transaksi dalam WIB, format `HH:mm` atau `HH:mm:ss`. Diabaikan saat jam bursa (tanggal hari ini, 08:45–16:15 WIB pada hari bursa); hanya berlaku pada pengambilan data sehari penuh. Example: `09:00:00`. */
  timefrom?: string;
  /** Jam akhir transaksi dalam WIB, format `HH:mm` atau `HH:mm:ss`. Tanpa detik, dihitung hingga detik ke-59. Diabaikan saat jam bursa (tanggal hari ini, 08:45–16:15 WIB pada hari bursa); hanya berlaku pada pengambilan data sehari penuh. Example: `16:00:00`. */
  timeto?: string;
  /** Arah pengurutan: `ASC` = menaik (terlama lebih dulu), `DESC` = menurun (terbaru lebih dulu). Diabaikan saat jam bursa (tanggal hari ini, 08:45–16:15 WIB pada hari bursa); hanya berlaku pada pengambilan data sehari penuh. Default: `ASC`. Example: `DESC`. */
  sort?: "ASC" | "DESC";
}

